ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS assigned_technicians jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS technician_source text; ALTER TABLE public.send_queue ADD COLUMN IF NOT EXISTS assigned_technicians jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.send_queue ADD COLUMN IF NOT EXISTS technician_source text; CREATE OR REPLACE FUNCTION public.ripple_sync_queue_technicians() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF TG_TABLE_NAME = 'jobs' THEN UPDATE public.send_queue q SET assigned_technicians = NEW.assigned_technicians, technician_source=NEW.technician_source WHERE q.job_id=NEW.id AND q.location_id=NEW.location_id AND (q.assigned_technicians IS DISTINCT FROM NEW.assigned_technicians OR q.technician_source IS DISTINCT FROM NEW.technician_source); RETURN NEW; ELSE SELECT j.assigned_technicians,j.technician_source INTO NEW.assigned_technicians, NEW.technician_source FROM public.jobs j WHERE j.id=NEW.job_id AND j.location_id=NEW.location_id; RETURN NEW; END IF; END $$; DROP TRIGGER IF EXISTS ripple_tech_job_sync ON public.jobs; CREATE TRIGGER ripple_tech_job_sync AFTER INSERT OR UPDATE OF assigned_technicians,technician_source ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.ripple_sync_queue_technicians(); DROP TRIGGER IF EXISTS ripple_tech_queue_copy ON public.send_queue; CREATE TRIGGER ripple_tech_queue_copy BEFORE INSERT OR UPDATE OF job_id ON public.send_queue FOR EACH ROW EXECUTE FUNCTION public.ripple_sync_queue_technicians(); UPDATE public.send_queue q SET assigned_technicians=j.assigned_technicians,technician_source=j.technician_source FROM public.jobs j WHERE q.job_id=j.id AND q.location_id=j.location_id AND (q.assigned_technicians IS DISTINCT FROM j.assigned_technicians OR q.technician_source IS DISTINCT FROM j.technician_source); CREATE INDEX IF NOT EXISTS idx_ripple_queue_assigned_tech ON public.send_queue USING gin (assigned_technicians);